<section class="settings-group"><x-section-heading tag="h3" icon="settings" tone="info">Shop details</x-section-heading><p>Used in the app and receipt header.</p><x-input id="shop_name" name="values[shop_name]" label="Shop display name" :value="old('values.shop_name',$values['shop_name'])" required maxlength="160" /><x-input id="address" name="values[address]" label="Shop address · optional" :value="old('values.address',$values['address'])" maxlength="500" /><p class="measure-note">Optional until the shop provides its address.</p><x-input id="contact" name="values[contact]" label="Shop contact number · optional" :value="old('values.contact',$values['contact'])" maxlength="40" inputmode="tel" /></section>
<section class="settings-group"><x-section-heading tag="h3" icon="settings" tone="info">Region & record format</x-section-heading><input type="hidden" name="values[currency]" value="PHP"><input type="hidden" name="values[timezone]" value="Asia/Manila"><x-setting-value label="Currency" value="PHP · Philippine peso" /><x-setting-value label="Timezone" value="Philippine time (UTC+8)" /><x-setting-value label="Date format" value="Day Month Year · 24-hour time" /><x-setting-value label="Branch scope" value="One branch" /><x-setting-value label="Tax configuration" value="Unconfigured · academic demonstration" help="Receipts retain their demonstration label." /></section>
